import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';

// ---- inlined from pathfinding ----
/**
 * Weighted-grid search traces for the pathfinding comparison. All four searches are one
 * implementation parameterized by (weight on g, weight on h, unit vs terrain cost) — that
 * parameterization is the actual mathematical relationship between the algorithms.
 */

const PF_COLS = 30;
const PF_ROWS = 19;
const CELLS = PF_COLS * PF_ROWS;
const SEED = 20260818;

const PF_START = (PF_ROWS - 4) * PF_COLS + 2;
const PF_GOAL = 3 * PF_COLS + (PF_COLS - 3);

/** mulberry32: a fixed seed keeps the terrain identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const NOISE_COLS = 7;
const NOISE_ROWS = 5;

/**
 * Per-cell movement cost 1..4, from smoothed value noise so cheap valleys are contiguous.
 * The range is tuned, not arbitrary: against wider costs the Manhattan heuristic (cell
 * count x 1) is too weak to separate A* from Dijkstra visibly — at 1..9 the measured gap
 * was 535 vs 552 expansions; at 1..4 it is 386 vs 549.
 */
const terrain: number[] = (() => {
  const random = seededRandom(SEED);
  const nodes = Array.from({ length: (NOISE_COLS + 1) * (NOISE_ROWS + 1) }, () => random());
  const at = (cx: number, cy: number) => nodes[cy * (NOISE_COLS + 1) + cx];
  const smooth = (t: number) => t * t * (3 - 2 * t);

  const out: number[] = [];
  for (let row = 0; row < PF_ROWS; ++row) {
    for (let col = 0; col < PF_COLS; ++col) {
      const u = (col / (PF_COLS - 1)) * NOISE_COLS;
      const v = (row / (PF_ROWS - 1)) * NOISE_ROWS;
      const cx = Math.min(NOISE_COLS - 1, Math.floor(u));
      const cy = Math.min(NOISE_ROWS - 1, Math.floor(v));
      const fu = smooth(u - cx);
      const fv = smooth(v - cy);
      const value =
        at(cx, cy) * (1 - fu) * (1 - fv) +
        at(cx + 1, cy) * fu * (1 - fv) +
        at(cx, cy + 1) * (1 - fu) * fv +
        at(cx + 1, cy + 1) * fu * fv;
      out.push(1 + Math.round(3 * value * value));
    }
  }
  return out;
})();

interface Trace {
  name: string;
  /** Cells in the order the search settled them; ends at the goal. */
  settled: number[];
  /** Accumulated cost when reached, indexed by cell; used to colour the wave. */
  g: number[];
  /** Largest settled g, for normalizing colour across the run. */
  gMax: number;
  /** The recovered route, start to goal. */
  path: number[];
  /** Terrain cost of that route — the number that convicts greedy and acquits A*. */
  pathCost: number;
}

/** Manhattan distance to the goal; admissible because the cheapest cell costs 1. */
const heuristic = (i: number) =>
  Math.abs((i % PF_COLS) - (PF_GOAL % PF_COLS)) +
  Math.abs(((i / PF_COLS) | 0) - ((PF_GOAL / PF_COLS) | 0));

function search(name: string, weightG: number, weightH: number, unitCost: boolean): Trace {
  const g = new Array<number>(CELLS).fill(Infinity);
  const parent = new Array<number>(CELLS).fill(-1);
  const done = new Array<boolean>(CELLS).fill(false);
  const open: number[] = [PF_START];
  const settled: number[] = [];
  g[PF_START] = 0;

  const key = (i: number) => weightG * g[i] + weightH * heuristic(i);

  while (open.length) {
    let best = 0;
    for (let k = 1; k < open.length; ++k) if (key(open[k]) < key(open[best])) best = k;
    const cell = open[best];
    open[best] = open[open.length - 1];
    open.pop();
    if (done[cell]) continue;

    done[cell] = true;
    settled.push(cell);
    if (cell === PF_GOAL) break;

    const col = cell % PF_COLS;
    const row = (cell / PF_COLS) | 0;
    const around = [
      col > 0 ? cell - 1 : -1,
      col < PF_COLS - 1 ? cell + 1 : -1,
      row > 0 ? cell - PF_COLS : -1,
      row < PF_ROWS - 1 ? cell + PF_COLS : -1
    ];
    for (const next of around) {
      if (next < 0 || done[next]) continue;
      const cost = g[cell] + (unitCost ? 1 : terrain[next]);
      if (cost < g[next]) {
        g[next] = cost;
        parent[next] = cell;
        open.push(next);
      }
    }
  }

  const path: number[] = [];
  for (let i = PF_GOAL; i >= 0; i = i === PF_START ? -1 : parent[i]) path.push(i);
  path.reverse();

  const gMax = Math.max(...settled.map((i) => g[i]));
  const pathCost = path.filter((i) => i !== PF_START).reduce((sum, i) => sum + terrain[i], 0);
  return { name, settled, g, gMax, path, pathCost };
}

const traces: Trace[] = [
  search('Breadth-first', 1, 0, true),
  search('Dijkstra', 1, 0, false),
  search('Greedy best-first', 0, 1, false),
  search('A*', 1, 1, false)
];

const TICK_MS = 45;
const TARGET_TICKS = 220;
const HOLD_TICKS = 40;
const GAP = 10;
const LABEL_HEIGHT = 15;
const BANDS = 8;

const maxSettled = Math.max(...traces.map((t) => t.settled.length));

const cellSquare = (i: number, size: number): string => {
  const x = (i % PF_COLS) * size;
  const y = ((i / PF_COLS) | 0) * size;
  return `M${x.toFixed(1)},${y.toFixed(1)}h${size.toFixed(1)}v${size.toFixed(1)}h${(-size).toFixed(1)}Z`;
};

const cellCenter = (i: number, size: number): [number, number] => [
  ((i % PF_COLS) + 0.5) * size,
  (((i / PF_COLS) | 0) + 0.5) * size
];

export default function PathfindingCompared({ width }: { width: number }) {
  const panelWidth = Math.max(1, (width - GAP) / 2);
  const cell = panelWidth / PF_COLS;
  const gridHeight = cell * PF_ROWS;
  const panelHeight = LABEL_HEIGHT + gridHeight;
  const height = Math.round(2 * panelHeight + GAP + 4);

  // The SSR frame is all four searches complete; the effect rewinds and replays them.
  const [count, setCount] = useState(maxSettled);

  useEffect(() => {
    const perTick = Math.max(1, Math.ceil(maxSettled / TARGET_TICKS));
    const end = maxSettled + perTick * HOLD_TICKS;
    setCount(0);
    const id = window.setInterval(() => setCount((c) => (c >= end ? 0 : c + perTick)), TICK_MS);
    return () => window.clearInterval(id);
  }, []);

  /** Terrain drawn once per cell size as one banded path per cost value. */
  const terrainBands = useMemo(() => {
    const byCost = new Map<number, string[]>();
    terrain.forEach((cost, i) => {
      const list = byCost.get(cost) ?? [];
      list.push(cellSquare(i, cell));
      byCost.set(cost, list);
    });
    return [...byCost].map(([cost, squares]) => ({ cost, d: squares.join('') }));
  }, [cell]);

  const panels = useMemo(
    () =>
      traces.map((trace) => {
        const shown = Math.min(count, trace.settled.length);
        const byBand = new Map<number, string[]>();
        for (let k = 0; k < shown; ++k) {
          const i = trace.settled[k];
          const band = Math.min(BANDS - 1, Math.floor((trace.g[i] / trace.gMax) * BANDS));
          const list = byBand.get(band) ?? [];
          list.push(cellSquare(i, cell));
          byBand.set(band, list);
        }
        return {
          name: trace.name,
          shown,
          done: shown >= trace.settled.length,
          pathCost: trace.pathCost,
          bands: [...byBand].map(([band, squares]) => ({ band, d: squares.join('') })),
          route: trace.path.map((i) => cellCenter(i, cell))
        };
      }),
    [count, cell]
  );

  if (width === 0) return null;

  const [startX, startY] = cellCenter(PF_START, cell);
  const [goalX, goalY] = cellCenter(PF_GOAL, cell);

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Four pathfinding searches racing on one shared weighted terrain: breadth-first and Dijkstra expand broad waves, greedy best-first stabs a narrow tongue toward the goal, and A-star explores the ellipse between them, each panel counting the cells it expanded"
    >
      {panels.map((panel, p) => {
        const px = (p % 2) * (panelWidth + GAP);
        const py = ((p / 2) | 0) * (panelHeight + GAP);
        return (
          <g key={panel.name} transform={`translate(${px},${py})`}>
            <text x={0} y={10} fill="var(--text)" fontSize={11} fontWeight={600}>
              {panel.name}
            </text>
            <text x={panelWidth} y={10} textAnchor="end" fill="var(--muted)" fontSize={11}>
              {panel.done ? `${panel.shown} expanded · route costs ${panel.pathCost}` : `${panel.shown} expanded`}
            </text>
            <g transform={`translate(0,${LABEL_HEIGHT})`}>
              {terrainBands.map(({ cost, d }) => (
                <path key={cost} d={d} fill="var(--muted)" opacity={((cost - 1) / 8) * 0.38} />
              ))}
              {panel.bands.map(({ band, d }) => (
                <path
                  key={band}
                  d={d}
                  fill={d3.interpolateTurbo(0.08 + 0.78 * (band / (BANDS - 1)))}
                  opacity={0.82}
                />
              ))}
              {panel.done && (
                <path
                  d={panel.route.map(([x, y], k) => `${k ? 'L' : 'M'}${x.toFixed(1)},${y.toFixed(1)}`).join('')}
                  fill="none"
                  stroke="var(--text)"
                  strokeWidth={Math.max(1.5, cell * 0.3)}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              )}
              <circle cx={startX} cy={startY} r={cell * 0.42} fill="var(--text)" />
              <circle
                cx={goalX}
                cy={goalY}
                r={cell * 0.42}
                fill="none"
                stroke="var(--text)"
                strokeWidth={Math.max(1, cell * 0.16)}
              />
            </g>
          </g>
        );
      })}
    </svg>
  );
}
